 accept(data){if(data.revision<this.revision)return;this.ack=data.campaign;this.revision=data.revision;this.queue=this.queue.filter(q=>!(data.applied??[]).includes(q.id));this.store();try{const c=this.current();if(!this.paused)this.onCampaign(c);this.onStatus(this.paused?'conflict':this.queue.length?'pending':'saved');}catch(e){this.paused=true;this.onStatus('conflict');this.onConflict('同伴已修改同一项。请先导出自己的副本，或采用房间版本。');}}
 async drain(){if(this.sending||this.paused||!this.queue.length||!this.ack)return;this.sending=true;try{while(this.queue.length&&!this.paused){const change=this.queue[0],data=await(await this.request('/changes',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(change)})).json();this.queue.shift();this.store();this.accept(data);}}catch(e){if(e.name==='AbortError')return;if(e.status>=400&&e.status<500){if(e.data.campaign){this.ack=e.data.campaign;this.revision=e.data.revision;}this.paused=true;this.onStatus('conflict');this.onConflict(e.message);}else{this.onStatus('offline');this.retry=setTimeout(()=>this.drain(),4000);}}finally{this.sending=false;if(this.deferred&&!this.paused){const data=this.deferred;this.deferred=null;this.accept(data);}}}
 async stream(){if(this.controller.signal.aborted)return;try{const response=await this.request('/events'),reader=response.body.getReader(),decoder=new TextDecoder();let buffer='';while(!this.controller.signal.aborted){const{value,done}=await reader.read();if(done)break;buffer+=decoder.decode(value,{stream:true});let end;while((end=buffer.indexOf('\n\n'))>=0){const event=buffer.slice(0,end);buffer=buffer.slice(end+2);if(event.startsWith('data: ')){const data=JSON.parse(event.slice(6));if(this.sending&&this.queue.length){this.deferred=data;continue;}this.accept(data);}}}}catch(e){if(e.name==='AbortError')return;this.onStatus('offline');}if(!this.controller.signal.aborted)this.reconnect=setTimeout(()=>{this.stream();this.drain();},3000);}
